// Create initializes the cuDNN library and creates a handle to an opaque structure holding the cuDNN library context.
//
// It allocates hardware resources on the host and device and must be called prior to making any other cuDNN library calls.
// The cuDNN library handle is tied to the current CUDA device (context). To use the library on multiple devices, one cuDNN handle needs to be created for each device.
// For a given device, multiple cuDNN handles with different configurations (for example, different current CUDA streams) may be created. Because [Create] allocates some internal resources, the release of those resources by calling [Handle.Close] will implicitly call cudaDeviceSynchronize; therefore, the recommended best practice is to call [Create] or [Handle.Close] outside of performance-critical code paths.
// For multithreaded applications that use the same device from different threads, the recommended programming model is to create one (or a few, as is convenient) cuDNN handles per thread and use that cuDNN handle for the entire life of the thread.
//
// A nil error means cuDNN handle was created successfully.
//
// Errors:
//   - [ErrAllocFailed]: Host memory allocation failed.
//   - [ErrArchMismatch]: NVIDIA GPU architecture is too old.
//   - [ErrBadParam]: Invalid ( NULL) input pointer supplied.
//   - [ErrInternalError]: CUDA resource allocation failed.
//   - [ErrLicenseError]: cuDNN license validation failed (only when the feature is enabled).
//   - [ErrNotInitialized]: No compatible GPU found, CUDA driver not installed or disabled, CUDA runtime API initialization failed.
//
// Wraps cudnnCreate.
func Create() (Handle, error) {
	if err := checkLibSym("cudnnCreate"); err != nil {
		var zero Handle
		return zero, err
	}
	out := slotCreate.get()
	defer slotCreate.put(out)
	if err := toError(fnCreate(out), "cudnnCreate"); err != nil {
		var zero Handle
		return zero, err
	}
	return *out, nil
}

var slotCreate outSlot[Handle]

