//
// Errors:
//   - [ErrBadParam]: An invalid input argument was found ( rnnDesc was NULL).
//
// Wraps cudnnRNNGetClip_v9.
func rNNGetClip(rnnDesc RNNDescriptor) (RNNClipMode, float64, float64, error) {
	if err := checkLibSym("cudnnRNNGetClip_v9"); err != nil {
		return *new(RNNClipMode), 0, 0, err
	}
	out := slotRNNGetClip.get()
	defer slotRNNGetClip.put(out)
	if err := toError(fnrNNGetClip(rnnDesc, &(*out).v0, &(*out).v1, &(*out).v2), "cudnnRNNGetClip_v9"); err != nil {
		return *new(RNNClipMode), 0, 0, err
	}
	return (*out).v0, (*out).v1, (*out).v2, nil
}

var slotRNNGetClip outSlot[struct {
	v0 RNNClipMode
	v1 float64
	v2 float64
}]

// rNNSetClip sets the LSTM cell clipping mode.
